func trap(height []int) int {
	l, r, lm, rm, ans := 0, len(height)-1, 0, 0, 0
	for l <= r {
		lm = max(lm, height[l])
		rm = max(rm, height[r])
		if lm <= rm {
			ans += lm - height[l]
			l++
		} else {
			ans += rm - height[r]
			r--
		}
	}
	return ans
}

valid-palindrome.go:
func isPalindrome(s string) bool {
	valid := func(c byte) bool { return c >= 'a' && c <= 'z' || c >= 'A' && c <= 'Z' || c >= '0' && c <= '9' }
	lower := func(c byte) byte {
		if c >= 'A' && c <= 'Z' {
			return c + 32
		}
		return c
	}
	l, r := 0, len(s)-1
	for l < r {
		if !valid(s[l]) {
			l++
			continue
		}
		if !valid(s[r]) {
			r--
			continue
		}
		if lower(s[l]) != lower(s[r]) {
			return false
		}
		l++
		r--
	}
	return true
}

