func lengthOfLongestSubstring(s string) int {
	last := map[byte]int{}
	l, ans := 0, 0
	for r := 0; r < len(s); r++ {
		if p, ok := last[s[r]]; ok && p >= l {
			l = p + 1
		}
		last[s[r]] = r
		ans = max(ans, r-l+1)
	}
	return ans
}

