func minWindow(s, t string) string {
	if len(t) == 0 {
		return ""
	}
	need := [256]int{}
	for i := range t {
		need[t[i]]++
	}
	missing, l, start, best := len(t), 0, 0, len(s)+1
	for r := range s {
		if need[s[r]] > 0 {
			missing--
		}
		need[s[r]]--
		for missing == 0 {
			if r-l+1 < best {
				start, best = l, r-l+1
			}
			need[s[l]]++
			if need[s[l]] > 0 {
				missing++
			}
			l++
		}
	}
	if best > len(s) {
		return ""
	}
	return s[start : start+best]
}

