func findMaxAverage(nums []int, k int) float64 {
	sum := 0
	for _, x := range nums[:k] {
		sum += x
	}
	best := sum
	for i := k; i < len(nums); i++ {
		sum += nums[i] - nums[i-k]
		best = max(best, sum)
	}
	return float64(best) / float64(k)
}

