func groupAnagrams(strs []string) [][]string {
	groups := map[[26]int]int{}
	ans := [][]string{}
	for _, s := range strs {
		k := [26]int{}
		for i := range s {
			k[s[i]-'a']++
		}
		j, ok := groups[k]
		if !ok {
			j = len(ans)
			groups[k] = j
			ans = append(ans, []string{})
		}
		ans[j] = append(ans[j], s)
	}
	return ans
}

