func checkSubarraySum(nums []int, k int) bool {
	first := map[int64]int{0: -1}
	var s int64
	for i, x := range nums {
		s += int64(x)
		r := s
		if k != 0 {
			r = s % int64(k)
		}
		if j, ok := first[r]; ok {
			if i-j >= 2 {
				return true
			}
		} else {
			first[r] = i
		}
	}
	return false
}

