type NumMatrix struct{ p [][]int }

func Constructor(matrix [][]int) NumMatrix {
	m := len(matrix)
	n := 0
	if m > 0 {
		n = len(matrix[0])
	}
	p := make([][]int, m+1)
	for i := range p {
		p[i] = make([]int, n+1)
	}
	for i := 0; i < m; i++ {
		for j := 0; j < n; j++ {
			p[i+1][j+1] = p[i][j+1] + p[i+1][j] - p[i][j] + matrix[i][j]
		}
	}
	return NumMatrix{p}
}
func (a *NumMatrix) SumRegion(r1, c1, r2, c2 int) int {
	p := a.p
	return p[r2+1][c2+1] - p[r1][c2+1] - p[r2+1][c1] + p[r1][c1]
}

