func searchRange(nums []int, target int) []int {
	bound := func(strict bool) int {
		l, r := 0, len(nums)
		for l < r {
			m := l + (r-l)/2
			if nums[m] < target || (strict && nums[m] == target) {
				l = m + 1
			} else {
				r = m
			}
		}
		return l
	}
	a := bound(false)
	if a == len(nums) || nums[a] != target {
		return []int{-1, -1}
	}
	return []int{a, bound(true) - 1}
}

search-a-2d-matrix.go:
func searchMatrix(matrix [][]int, target int) bool {
	if len(matrix) == 0 || len(matrix[0]) == 0 {
		return false
	}
	n := len(matrix[0])
	l, r := 0, len(matrix)*n
	for l < r {
		m := l + (r-l)/2
		if matrix[m/n][m%n] < target {
			l = m + 1
		} else {
			r = m
		}
	}
	return l < len(matrix)*n && matrix[l/n][l%n] == target
}

