func deleteNode(root *TreeNode, key int) *TreeNode {
	if root == nil {
		return nil
	}
	if key < root.Val {
		root.Left = deleteNode(root.Left, key)
	} else if key > root.Val {
		root.Right = deleteNode(root.Right, key)
	} else {
		if root.Left == nil {
			return root.Right
		}
		if root.Right == nil {
			return root.Left
		}
		s := root.Right
		for s.Left != nil {
			s = s.Left
		}
		root.Val = s.Val
		root.Right = deleteNode(root.Right, s.Val)
	}
	return root
}

