func ladderLength(beginWord, endWord string, wordList []string) int {
	dict := map[string]bool{}
	for _, w := range wordList {
		dict[w] = true
	}
	if !dict[endWord] {
		return 0
	}
	delete(dict, beginWord)
	q := []string{beginWord}
	steps := 1
	for len(q) > 0 {
		size := len(q)
		for i := 0; i < size; i++ {
			w := q[0]
			q = q[1:]
			if w == endWord {
				return steps
			}
			b := []byte(w)
			for j, old := range b {
				for c := byte('a'); c <= 'z'; c++ {
					b[j] = c
					s := string(b)
					if dict[s] {
						delete(dict, s)
						q = append(q, s)
					}
				}
				b[j] = old
			}
		}
		steps++
	}
	return 0
}

