func openLock(deadends []string, target string) int {
	seen := map[string]bool{}
	for _, s := range deadends {
		seen[s] = true
	}
	if seen["0000"] {
		return -1
	}
	q := []string{"0000"}
	seen["0000"] = true
	steps := 0
	for len(q) > 0 {
		size := len(q)
		for i := 0; i < size; i++ {
			s := q[0]
			q = q[1:]
			if s == target {
				return steps
			}
			b := []byte(s)
			for j, old := range b {
				for _, d := range []int{1, 9} {
					b[j] = byte((int(old-'0')+d)%10) + '0'
					v := string(b)
					if !seen[v] {
						seen[v] = true
						q = append(q, v)
					}
				}
				b[j] = old
			}
		}
		steps++
	}
	return -1
}

