func shortestPathBinaryMatrix(grid [][]int) int {
	n := len(grid)
	if n == 0 || grid[0][0] != 0 || grid[n-1][n-1] != 0 {
		return -1
	}
	q := [][2]int{{0, 0}}
	grid[0][0] = 1
	distance := 1
	for len(q) > 0 {
		size := len(q)
		for i := 0; i < size; i++ {
			v := q[0]
			q = q[1:]
			if v == [2]int{n - 1, n - 1} {
				return distance
			}
			for dr := -1; dr <= 1; dr++ {
				for dc := -1; dc <= 1; dc++ {
					r, c := v[0]+dr, v[1]+dc
					if r >= 0 && r < n && c >= 0 && c < n && grid[r][c] == 0 {
						grid[r][c] = 1
						q = append(q, [2]int{r, c})
					}
				}
			}
		}
		distance++
	}
	return -1
}

