		}
	}
	for i := 0; i < len(q); i++ {
		for _, w := range g[q[i]] {
			in[w]--
			if in[w] == 0 {
				q = append(q, w)
			}
		}
	}
	if len(q) != n {
		return []int{}
	}
	return q
}
