type unionFind struct{ p, size []int }

func newUF(n int) *unionFind {
	p, s := make([]int, n), make([]int, n)
	for i := range p {
		p[i] = i
		s[i] = 1
	}
	return &unionFind{p, s}
}
func (u *unionFind) find(x int) int {
	for x != u.p[x] {
		u.p[x] = u.p[u.p[x]]
		x = u.p[x]
	}
	return x
}
func (u *unionFind) join(a, b int) bool {
	a, b = u.find(a), u.find(b)
	if a == b {
		return false
	}
	if u.size[a] < u.size[b] {
		a, b = b, a
	}
	u.p[b] = a
	u.size[a] += u.size[b]
	return true
}
func findRedundantConnection(edges [][]int) []int {
	u := newUF(len(edges) + 1)
	for _, e := range edges {
		if !u.join(e[0], e[1]) {
			return e
		}
	}
	return nil
}

