func findItinerary(tickets [][]string) []string {
	g := map[string][]string{}
	for _, t := range tickets {
		g[t[0]] = append(g[t[0]], t[1])
	}
	for v := range g {
		sort.Sort(sort.Reverse(sort.StringSlice(g[v])))
	}
	ans := []string{}
	var dfs func(string)
	dfs = func(v string) {
		for len(g[v]) > 0 {
			a := g[v]
			w := a[len(a)-1]
			g[v] = a[:len(a)-1]
			dfs(w)
		}
		ans = append(ans, v)
	}
	dfs("JFK")
	for l, r := 0, len(ans)-1; l < r; l, r = l+1, r-1 {
		ans[l], ans[r] = ans[r], ans[l]
	}
	return ans
}

