import "math/bits"

func solveSudoku(board [][]byte) {
	var rows, cols, boxes [9]int
	cells := [][2]int{}
	for r := 0; r < 9; r++ {
		for c := 0; c < 9; c++ {
			if board[r][c] == '.' {
				cells = append(cells, [2]int{r, c})
			} else {
				b := 1 << int(board[r][c]-'1')
				rows[r] |= b
				cols[c] |= b
				boxes[r/3*3+c/3] |= b
			}
		}
	}
	mask := func(r, c int) int { return 511 & ^(rows[r] | cols[c] | boxes[r/3*3+c/3]) }
	var dfs func(int) bool
	dfs = func(i int) bool {
		if i == len(cells) {
			return true
		}
		best := i
		for j := i + 1; j < len(cells); j++ {
			if bits.OnesCount(uint(mask(cells[j][0], cells[j][1]))) < bits.OnesCount(uint(mask(cells[best][0], cells[best][1]))) {
				best = j
			}
		}
		cells[i], cells[best] = cells[best], cells[i]
		r, c := cells[i][0], cells[i][1]
		box := r/3*3 + c/3
		for m := mask(r, c); m != 0; m &= m - 1 {
			b := m & -m
			board[r][c] = byte(bits.TrailingZeros(uint(b))) + '1'
			rows[r] |= b
			cols[c] |= b
			boxes[box] |= b
			if dfs(i + 1) {
				return true
			}
			rows[r] ^= b
			cols[c] ^= b
			boxes[box] ^= b
			board[r][c] = '.'
		}
		cells[i], cells[best] = cells[best], cells[i]
		return false
	}
	dfs(0)
}

