func generateParenthesis(n int) []string {
	ans := []string{}
	path := []byte{}
	var dfs func(int, int)
	dfs = func(open, close int) {
		if close == n {
			ans = append(ans, string(path))
			return
		}
		if open < n {
			path = append(path, '(')
			dfs(open+1, close)
			path = path[:len(path)-1]
		}
		if close < open {
			path = append(path, ')')
			dfs(open, close+1)
			path = path[:len(path)-1]
		}
	}
	dfs(0, 0)
	return ans
}

