func coinChange(coins []int, amount int) int {
	dp := make([]int, amount+1)
	for s := 1; s <= amount; s++ {
		dp[s] = amount + 1
		for _, c := range coins {
			if c <= s {
				dp[s] = min(dp[s], dp[s-c]+1)
			}
		}
	}
	if dp[amount] > amount {
		return -1
	}
	return dp[amount]
}

