func minPathSum(grid [][]int) int {
	n := len(grid[0])
	dp := make([]int, n)
	for r := range grid {
		for c, x := range grid[r] {
			if r == 0 && c == 0 {
				dp[c] = x
			} else if r == 0 {
				dp[c] = dp[c-1] + x
			} else if c == 0 {
				dp[c] += x
			} else {
				dp[c] = min(dp[c], dp[c-1]) + x
			}
		}
	}
	return dp[n-1]
}

