func longestPalindrome(s string) string {
	n := len(s)
	if n == 0 {
		return ""
	}
	dp := make([][]bool, n)
	for i := range dp {
		dp[i] = make([]bool, n)
	}
	start, best := 0, 1
	for length := 1; length <= n; length++ {
		for l := 0; l+length <= n; l++ {
			r := l + length - 1
			dp[l][r] = s[l] == s[r] && (length <= 2 || dp[l+1][r-1])
			if dp[l][r] && length > best {
				start, best = l, length
			}
		}
	}
	return s[start : start+best]
}

