import "container/heap"

type intHeap []int

func (h intHeap) Len() int           { return len(h) }
func (h intHeap) Less(i, j int) bool { return h[i] < h[j] }
func (h intHeap) Swap(i, j int)      { h[i], h[j] = h[j], h[i] }
func (h *intHeap) Push(x any)        { *h = append(*h, x.(int)) }
func (h *intHeap) Pop() any          { a := *h; x := a[len(a)-1]; *h = a[:len(a)-1]; return x }

type MedianFinder struct{ low, high intHeap }

func Constructor() MedianFinder { return MedianFinder{} }
func (m *MedianFinder) AddNum(num int) {
	heap.Push(&m.low, -num)
	heap.Push(&m.high, -heap.Pop(&m.low).(int))
	if len(m.high) > len(m.low) {
		heap.Push(&m.low, -heap.Pop(&m.high).(int))
	}
}
func (m *MedianFinder) FindMedian() float64 {
	if len(m.low) > len(m.high) {
		return -float64(m.low[0])
	}
	return (-float64(m.low[0]) + float64(m.high[0])) / 2
}

sliding-window-median.go:
import "container/heap"

type intHeap []int

func (h intHeap) Len() int           { return len(h) }
func (h intHeap) Less(i, j int) bool { return h[i] < h[j] }
func (h intHeap) Swap(i, j int)      { h[i], h[j] = h[j], h[i] }
func (h *intHeap) Push(x any)        { *h = append(*h, x.(int)) }
func (h *intHeap) Pop() any          { a := *h; x := a[len(a)-1]; *h = a[:len(a)-1]; return x }

type dualHeap struct {
	low, high intHeap
	dead      map[int]int
	lo, hi    int
}

func (d *dualHeap) prune(low bool) {
	h := &d.high
	if low {
		h = &d.low
	}
	for h.Len() > 0 {
		x := (*h)[0]
		if low {
			x = -x
		}
		if d.dead[x] == 0 {
			break
		}
		d.dead[x]--
		if d.dead[x] == 0 {
			delete(d.dead, x)
		}
		heap.Pop(h)
	}
}
func (d *dualHeap) balance() {
	if d.lo > d.hi+1 {
		heap.Push(&d.high, -heap.Pop(&d.low).(int))
		d.lo--
		d.hi++
		d.prune(true)
	} else if d.lo < d.hi {
		heap.Push(&d.low, -heap.Pop(&d.high).(int))
		d.lo++
		d.hi--
		d.prune(false)
	}
}
func (d *dualHeap) add(x int) {
	d.prune(true)
	if d.lo == 0 || x <= -d.low[0] {
		heap.Push(&d.low, -x)
		d.lo++
	} else {
		heap.Push(&d.high, x)
		d.hi++
	}
	d.balance()
}
func (d *dualHeap) remove(x int) {
	d.prune(true)
	d.dead[x]++
	if x <= -d.low[0] {
		d.lo--
		d.prune(true)
	} else {
		d.hi--
		d.prune(false)
	}
	d.balance()
}
func (d *dualHeap) median() float64 {
	d.prune(true)
	d.prune(false)
	if d.lo > d.hi {
		return -float64(d.low[0])
	}
	return (-float64(d.low[0]) + float64(d.high[0])) / 2
}
func medianSlidingWindow(nums []int, k int) []float64 {
	d := &dualHeap{dead: map[int]int{}}
	ans := []float64{}
	for i, x := range nums {
		d.add(x)
		if i >= k {
			d.remove(nums[i-k])
		}
		if i >= k-1 {
			if len(d.low)+len(d.high) > 2*k {
				d = &dualHeap{dead: map[int]int{}}
				for _, v := range nums[i-k+1 : i+1] {
					d.add(v)
				}
			}
			ans = append(ans, d.median())
		}
	}
	return ans
}

