func setZeroes(matrix [][]int) {
	if len(matrix) == 0 || len(matrix[0]) == 0 {
		return
	}
	m, n := len(matrix), len(matrix[0])
	row0, col0 := false, false
	for _, x := range matrix[0] {
		row0 = row0 || x == 0
	}
	for r := 0; r < m; r++ {
		col0 = col0 || matrix[r][0] == 0
	}
	for r := 1; r < m; r++ {
		for c := 1; c < n; c++ {
			if matrix[r][c] == 0 {
				matrix[r][0] = 0
				matrix[0][c] = 0
			}
		}
	}
	for r := 1; r < m; r++ {
		for c := 1; c < n; c++ {
			if matrix[r][0] == 0 || matrix[0][c] == 0 {
				matrix[r][c] = 0
			}
		}
	}
	if row0 {
		for c := 0; c < n; c++ {
			matrix[0][c] = 0
		}
	}
	if col0 {
		for r := 0; r < m; r++ {
			matrix[r][0] = 0
		}
	}
}

