func rotate(nums []int, k int) {
	if len(nums) == 0 {
		return
	}
	k %= len(nums)
	rev := func(a []int) {
		for l, r := 0, len(a)-1; l < r; l, r = l+1, r-1 {
			a[l], a[r] = a[r], a[l]
		}
	}
	rev(nums)
	rev(nums[:k])
	rev(nums[k:])
}

