type Trie struct {
	children [26]*Trie
	end      bool
}

func Constructor() Trie { return Trie{} }
func (t *Trie) Insert(word string) {
	for i := range word {
		j := word[i] - 'a'
		if t.children[j] == nil {
			t.children[j] = &Trie{}
		}
		t = t.children[j]
	}
	t.end = true
}
func (t *Trie) walk(s string) *Trie {
	for i := range s {
		t = t.children[s[i]-'a']
		if t == nil {
			return nil
		}
	}
	return t
}
func (t *Trie) Search(word string) bool       { n := t.walk(word); return n != nil && n.end }
func (t *Trie) StartsWith(prefix string) bool { return t.walk(prefix) != nil }

