}
func (t *WordDictionary) Search(word string) bool {
	if t == nil {
		return false
	}
	if len(word) == 0 {
		return t.end
	}
	if word[0] == '.' {
		for _, child := range t.children {
			if child != nil && child.Search(word[1:]) {
				return true
			}
		}
		return false
	}
	return t.children[word[0]-'a'].Search(word[1:])
}

