type MyQueue struct{ in, out []int }

func Constructor() MyQueue    { return MyQueue{} }
func (q *MyQueue) Push(x int) { q.in = append(q.in, x) }
func (q *MyQueue) prepare() {
	if len(q.out) == 0 {
		for len(q.in) > 0 {
			i := len(q.in) - 1
			q.out = append(q.out, q.in[i])
			q.in = q.in[:i]
		}
	}
}
func (q *MyQueue) Pop() int {
	q.prepare()
	i := len(q.out) - 1
	x := q.out[i]
	q.out = q.out[:i]
	return x
}
func (q *MyQueue) Peek() int   { q.prepare(); return q.out[len(q.out)-1] }
func (q *MyQueue) Empty() bool { return len(q.in)+len(q.out) == 0 }

