func trap(height []int) int {
	st := []int{}
	ans := 0
	for r, h := range height {
		for len(st) > 0 && height[st[len(st)-1]] < h {
			bottom := st[len(st)-1]
			st = st[:len(st)-1]
			if len(st) == 0 {
				break
			}
			l := st[len(st)-1]
			ans += (min(height[l], h) - height[bottom]) * (r - l - 1)
		}
		st = append(st, r)
	}
	return ans
}

