type unionFind struct{ p, size []int }

func newUF(n int) *unionFind {
	p, s := make([]int, n), make([]int, n)
	for i := range p {
		p[i] = i
		s[i] = 1
	}
	return &unionFind{p, s}
}
func (u *unionFind) find(x int) int {
	for x != u.p[x] {
		u.p[x] = u.p[u.p[x]]
		x = u.p[x]
	}
	return x
}
func (u *unionFind) join(a, b int) bool {
	a, b = u.find(a), u.find(b)
	if a == b {
		return false
	}
	if u.size[a] < u.size[b] {
		a, b = b, a
	}
	u.p[b] = a
	u.size[a] += u.size[b]
	return true
}
func findCircleNum(isConnected [][]int) int {
	n := len(isConnected)
	u := newUF(n)
	ans := n
	for i := 0; i < n; i++ {
		for j := i + 1; j < n; j++ {
			if isConnected[i][j] == 1 && u.join(i, j) {
				ans--
			}
		}
	}
	return ans
}

