func maxProfit(prices []int) int {
	if len(prices) == 0 {
		return 0
	}
	hold, sold := -prices[0], 0
	for _, p := range prices[1:] {
		hold, sold = max(hold, -p), max(sold, hold+p)
	}
	return sold
}

