func longestValidParentheses(s string) int {
	st := []int{-1}
	ans := 0
	for i := range s {
		if s[i] == '(' {
			st = append(st, i)
		} else {
			st = st[:len(st)-1]
			if len(st) == 0 {
				st = append(st, i)
			} else {
				ans = max(ans, i-st[len(st)-1])
			}
		}
	}
	return ans
}
